def poblar_base_datos():
    db = SessionLocal()
    try:
        db.add_all(preguntas_arte)
        db.commit()
        print(f"Se insertaron {len(preguntas_arte)} preguntas de Arte correctamente.")
    except Exception as e:
        db.rollback()
        print(f"Error al insertar: {e}")
    finally:
        db.close()

if __name__ == "__main__":
    poblar_base_datos()